package com.sza.fastmediasorter.domain.model

/**
 * What the embedded SFTP server publishes on the outgoing exchange account entry (contract ANYWHERE-ACCESS
 * section 5). Off by default: with [enabled] false the server behaves exactly as the LAN-only server of S3041
 * (contract section 8). The server address, login and pin come from the account entry, not from here.
 */
data class SftpExchangeConfig(
    val enabled: Boolean,
    /** The share id of contract section 6.2; generated by the producer, never by the server. */
    val shareId: String,
) {

    // DIAGNOSTIC-REPORT section 10 and rule 3: the generated form printed the share id.
    override fun toString(): String = "SftpExchangeConfig(enabled=$enabled, shareId=${hidden(shareId)})"

    companion object {
        private const val HIDDEN = "[REDACTED]"

        // An absent value stays visible as absent: "no share id" is diagnostic, the id itself is not.
        private fun hidden(value: String): String = if (value.isEmpty()) value else HIDDEN

        /** The exchange server port assumed when an entered address carries none. */
        const val DEFAULT_PORT = 44_022
    }
}

/** What the producer's registration on the exchange server is doing. */
sealed interface SftpTunnelState {
    /** No exchange server configured, or the SFTP server is not running. */
    object Off : SftpTunnelState

    object Connecting : SftpTunnelState

    /** Registered; [publicPort] is the third-party port the server granted, if any (contract section 5.5). */
    data class Registered(val publicPort: Int?) : SftpTunnelState

    /** The server refused; [reason] is a contract section 6.3 reason string. Retries stop for a credential refusal. */
    data class Refused(val reason: String) : SftpTunnelState

    /** The server answered with a certificate other than the pinned one; retries stop until the pin is reset. */
    object CertificateChanged : SftpTunnelState

    /** The server could not be reached; the manager keeps retrying with backoff. */
    object Unreachable : SftpTunnelState
}
